 interface Pick{void go(int v);}AdapterView.OnItemSelectedListener listener(Pick x){return new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View v,int n,long l){x.go(n);}public void onNothingSelected(AdapterView<?>a){}};}
 Spinner sp(LinearLayout p,String label,String[] values){TextView t=new TextView(this);t.setText(label);t.setTextColor(0xffbbbbbb);t.setTextSize(11);p.addView(t);Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));p.addView(s);return s;}
 void thread(){ht=new HandlerThread("CM-Camera");ht.start();h=new Handler(ht.getLooper());if(view.isAvailable())open();}
 void open(){try{for(String x:cm.getCameraIdList()){CameraCharacteristics c=cm.getCameraCharacteristics(x);Integer f=c.get(CameraCharacteristics.LENS_FACING);if(f!=null&&f==CameraCharacteristics.LENS_FACING_BACK){id=x;Range<Long> r=c.get(CameraCharacteristics.SENSOR_INFO_EXPOSURE_TIME_RANGE);if(r!=null){minExp=r.getLower();maxExp=r.getUpper();}break;}}if(id==null){status.setText("NO BACK CAMERA");return;}if(checkSelfPermission(Manifest.permission.CAMERA)!=0)return;cm.openCamera(id,new CameraDevice.StateCallback(){public void onOpened(CameraDevice c){cam=c;preview();}public void onDisconnected(CameraDevice c){c.close();cam=null;}public void onError(CameraDevice c,int e){c.close();status.setText("CAMERA ERROR");}},h);}catch(Exception e){status.setText("CAMERA: "+e.getMessage());}}
 void preview(){try{SurfaceTexture t=view.getSurfaceTexture();if(t==null)return;t.setDefaultBufferSize(1920,1080);previewSurface=new Surface(t);previewReq=cam.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);previewReq.addTarget(previewSurface);controls(previewReq);cam.createCaptureSession(Collections.singletonList(previewSurface),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){session=s;try{s.setRepeatingRequest(previewReq.build(),null,h);status.setText("LIVE  •  BACK CAMERA");}catch(Exception e){status.setText(e.getMessage());}}public void onConfigureFailed(CameraCaptureSession s){status.setText("PREVIEW FAILED");}},h);}catch(Exception e){status.setText(e.getMessage());}}
 void controls(CaptureRequest.Builder b){try{int w=wbS==null?0:wbS.getSelectedItemPosition();int[] modes={1, daylight(), cloudy(), tungsten(), fluorescent()};b.set(CaptureRequest.CONTROL_AWB_MODE,modes[Math.min(w,4)]);b.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_OFF);b.set(CaptureRequest.LENS_FOCUS_DISTANCE,focus*10f);if(manual){b.set(CaptureRequest.CONTROL_AE_MODE,CaptureRequest.CONTROL_AE_MODE_OFF);b.set(CaptureRequest.SENSOR_SENSITIVITY,iso);b.set(CaptureRequest.SENSOR_EXPOSURE_TIME,Math.max(minExp,Math.min(maxExp,shutter)));}else b.set(CaptureRequest.CONTROL_AE_MODE,CaptureRequest.CONTROL_AE_MODE_ON);}catch(Exception ignored){}}
 int daylight(){return CaptureRequest.CONTROL_AWB_MODE_DAYLIGHT;}int cloudy(){return CaptureRequest.CONTROL_AWB_MODE_CLOUDY_DAYLIGHT;}int tungsten(){return CaptureRequest.CONTROL_AWB_MODE_INCANDESCENT;}int fluorescent(){return CaptureRequest.CONTROL_AWB_MODE_FLUORESCENT;}
 void apply(){if(session!=null&&previewReq!=null&&!recording)try{controls(previewReq);session.setRepeatingRequest(previewReq.build(),null,h);}catch(Exception ignored){}}
 void startRec(){if(cam==null)return;try{if(session!=null){session.close();session=null;}mr=new MediaRecorder();mr.setAudioSource(MediaRecorder.AudioSource.MIC);mr.setVideoSource(MediaRecorder.VideoSource.SURFACE);boolean full=resS.getSelectedItemPosition()==0;int width=full?1920:1280,height=full?1080:720;mr.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);mr.setVideoEncoder(MediaRecorder.VideoEncoder.H264);mr.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);mr.setVideoSize(width,height);int fps=fpsS.getSelectedItemPosition()==1?24:fpsS.getSelectedItemPosition()==2?60:30;mr.setVideoFrameRate(fps);mr.setVideoEncodingBitRate(full?18000000:8000000);File d=getExternalFilesDir(Environment.DIRECTORY_MOVIES);if(!d.exists())d.mkdirs();file=new File(d,"CM_"+System.currentTimeMillis()+".mp4");mr.setOutputFile(file.getAbsolutePath());mr.prepare();SurfaceTexture t=view.getSurfaceTexture();t.setDefaultBufferSize(width,height);Surface ps=new Surface(t),rs=mr.getSurface();CaptureRequest.Builder b=cam.createCaptureRequest(CameraDevice.TEMPLATE_RECORD);b.addTarget(ps);b.addTarget(rs);controls(b);cam.createCaptureSession(Arrays.asList(ps,rs),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){session=s;try{s.setRepeatingRequest(b.build(),null,h);mr.start();recording=true;runOnUiThread(()->{rec.setText("■  STOP");status.setText("● RECORDING");});}catch(Exception e){status.setText("REC ERROR");}}public void onConfigureFailed(CameraCaptureSession s){status.setText("RECORD SETUP FAILED");}},h);}catch(Exception e){status.setText("REC ERROR: "+e.getMessage());releaseRecorder();}}
 void stopRec(){try{if(session!=null){session.stopRepeating();session.abortCaptures();}mr.stop();status.setText("SAVED IN APP MOVIES: "+file.getName());}catch(Exception e){status.setText("CLIP TOO SHORT / ERROR");}recording=false;releaseRecorder();rec.setText("● RECORD");if(session!=null){session.close();session=null;}preview();}
 void releaseRecorder(){try{if(mr!=null){mr.reset();mr.release();mr=null;}}catch(Exception ignored){}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==8&&g.length>=2&&g[0]==0&&g[1]==0)thread();else status.setText("CAMERA AND MIC PERMISSION REQUIRED");}
 protected void onPause(){super.onPause();if(recording)stopRec();if(session!=null){session.close();session=null;}if(cam!=null){cam.close();cam=null;}}
 protected void onDestroy(){super.onDestroy();if(ht!=null){ht.quitSafely();ht=null;}}
